-- auth-svc: user accounts in the auth_svc schema
-- Not "auth": Supabase reserves that schema for its own Auth product.
CREATE SCHEMA IF NOT EXISTS auth_svc;

-- id is a UUIDv7 generated by the service, so inserts stay time-ordered.
-- email and username keep varchar limits on purpose (RFC 5321 address length,
-- URL-safe handle length); both are stored lowercase, which the CHECKs enforce
-- so the unique constraints are effectively case-insensitive.
CREATE TABLE IF NOT EXISTS auth_svc.users (
    id            UUID         PRIMARY KEY,
    email         VARCHAR(254) NOT NULL,
    username      VARCHAR(39)  NOT NULL,
    password_hash TEXT         NOT NULL,
    is_active     BOOLEAN      NOT NULL DEFAULT TRUE,
    created_at    TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT users_email_key       UNIQUE (email),
    CONSTRAINT users_username_key    UNIQUE (username),
    CONSTRAINT users_email_lower     CHECK (email = lower(email)),
    CONSTRAINT users_username_lower  CHECK (username = lower(username))
);
